{
  "requirements": [
    {
      "text": "The system shall continuously monitor the health and integrity of all sensors and actuators, and if any component degrades beyond predefined thresholds, the system shall immediately transition to a safe state (e.g., controlled stop) without requiring operator intervention."
    },
    {
      "text": "The system shall provide a reliable, multimodal driver‑takeover request (visual, audible, and haptic) whenever the automated driving system cannot guarantee safe operation, and shall require explicit driver acknowledgment within a bounded time (e.g., 2 seconds) before resuming autonomous control."
    },
    {
      "text": "The system shall be developed and validated in accordance with ISO 26262 (ASIL D for safety‑critical functions) and shall include documented safety cases, hazard analyses, and verification/validation evidence for all safety‑related software and hardware."
    },
    {
      "text": "The system shall implement redundant braking actuation such that loss of the primary brake command does not prevent the vehicle from achieving a required stopping distance (e.g., 30 ft at 45 mph) under any single‑point failure condition."
    },
    {
      "text": "The system shall enforce geofencing and speed‑limit compliance, ensuring the vehicle never exceeds the posted speed limit by more than 5 mph and automatically reduces speed or disengages autonomous mode when approaching restricted zones."
    },
    {
      "text": "The system shall perform continuous runtime verification of perception, prediction, and planning outputs against a set of safety rules (e.g., no‑collision trajectory, minimum time‑to‑collision thresholds) and shall abort autonomous control and request driver takeover if any rule violation is detected."
    },
    {
      "text": "The system shall provide an emergency‑stop capability that can be activated by the vehicle operator, a remote safety monitor, or automatically by the system, bringing the vehicle to a complete stop within a defined distance (e.g., 15 ft) regardless of current speed."
    },
    {
      "text": "The system shall record all raw sensor data, perception results, planning decisions, control commands, and operator interventions with precise timestamps, store logs securely to prevent tampering, and retain them for post‑incident analysis."
    },
    {
      "text": "The system shall display a clear, unambiguous status indicator (e.g., green/yellow/red) of ADS readiness on the operator’s tablet and shall prohibit autonomous driving unless the status is green."
    },
    {
      "text": "The system shall be validated for operation under all environmental conditions expected in the test area (e.g., rain, glare, low‑light, dust) and shall automatically disengage autonomous mode if environmental factors exceed the validated operational envelope."
    }
  ]
}
